//! Cross-language golden tests: the Rust baseline must reproduce the hit order
//! and distances produced by the TypeScript `exactVectorSearch` for the same
//! fixed datasets. Both fixtures are generated by
//! `tools/bench/rust-golden.mjs --write`, which CI re-runs in check mode to keep
//! the TypeScript side honest.

use std::str::FromStr;

use weisql_vector_benchmark::{exact_search, exact_search_contiguous, Metric};

const COSINE_FIXTURE: &str = include_str!("fixtures/exact_cosine_golden.txt");
const METRICS_FIXTURE: &str = include_str!("fixtures/metrics_golden.txt");

/// The TypeScript side serializes distances with nine decimals; both sides
/// accumulate in `f64` and only the Rust result is rounded to `f32`.
const TOLERANCE: f32 = 1e-6;

#[derive(Debug)]
struct Case {
    name: String,
    metric: Metric,
    rows: usize,
    dim: usize,
    top_k: usize,
    query: Vec<f32>,
    vectors: Vec<Vec<f32>>,
    hits: Vec<(usize, f32)>,
}

#[test]
fn rust_matches_the_typescript_cosine_fixture() {
    check(COSINE_FIXTURE, 6);
}

#[test]
fn rust_matches_the_typescript_metric_fixture() {
    let cases = parse(METRICS_FIXTURE);
    assert!(cases.iter().any(|case| case.metric == Metric::L2), "L2 must be covered");
    assert!(
        cases.iter().any(|case| case.metric == Metric::Ip),
        "inner product must be covered"
    );
    check(METRICS_FIXTURE, 3);
}

#[test]
fn golden_case_names_are_unique() {
    for fixture in [COSINE_FIXTURE, METRICS_FIXTURE] {
        let cases = parse(fixture);
        let mut names: Vec<&str> = cases.iter().map(|case| case.name.as_str()).collect();
        names.sort_unstable();
        names.dedup();
        assert_eq!(names.len(), cases.len(), "duplicate case name in a golden fixture");
    }
}

fn check(fixture: &str, expected_cases: usize) {
    let cases = parse(fixture);
    assert_eq!(cases.len(), expected_cases, "every golden case must be exercised");

    for case in &cases {
        assert_eq!(case.vectors.len(), case.rows, "case {}: row count", case.name);
        assert_eq!(case.query.len(), case.dim, "case {}: query width", case.name);
        assert!(
            case.vectors.iter().all(|row| row.len() == case.dim),
            "case {}: row width",
            case.name
        );
        assert!(!case.hits.is_empty(), "case {}: expected hits", case.name);

        let hits = exact_search(&case.vectors, &case.query, case.top_k, case.metric)
            .unwrap_or_else(|error| panic!("case {}: {error}", case.name));
        assert_eq!(hits.len(), case.hits.len(), "case {}: hit count", case.name);

        for (position, (actual, &(row, distance))) in hits.iter().zip(&case.hits).enumerate() {
            assert_eq!(actual.id, row, "case {} position {position}: rank order", case.name);
            assert!(
                (actual.distance - distance).abs() <= TOLERANCE,
                "case {} position {position}: rust {} vs typescript {distance}",
                case.name,
                actual.distance
            );
        }

        // The WASM shim calls the contiguous entry point, so the fixture must
        // hold for that layout too, bit for bit.
        let flat: Vec<f32> = case.vectors.iter().flatten().copied().collect();
        let contiguous = exact_search_contiguous(&flat, case.rows, case.dim, &case.query, case.top_k, case.metric)
            .unwrap_or_else(|error| panic!("case {} contiguous: {error}", case.name));
        assert_eq!(contiguous, hits, "case {}: contiguous layout differs", case.name);
    }
}

fn parse(text: &str) -> Vec<Case> {
    let mut cases: Vec<Case> = Vec::new();
    let mut current: Option<Case> = None;

    for (index, raw) in text.lines().enumerate() {
        let line = index + 1;
        let row = raw.trim();
        if row.is_empty() || row.starts_with('#') {
            continue;
        }
        let mut fields = row.split_whitespace();
        match fields.next().unwrap_or_default() {
            "case" => {
                if let Some(case) = current.take() {
                    cases.push(case);
                }
                let name = fields
                    .next()
                    .unwrap_or_else(|| panic!("line {line}: case needs a name"))
                    .to_string();
                let rows = number::<usize>(fields.next(), "rows", line);
                let dim = number::<usize>(fields.next(), "dimension", line);
                let top_k = number::<usize>(fields.next(), "top_k", line);
                current = Some(Case {
                    name,
                    metric: Metric::Cosine,
                    rows,
                    dim,
                    top_k,
                    query: Vec::new(),
                    vectors: Vec::new(),
                    hits: Vec::new(),
                });
            }
            "metric" => {
                let case = case_mut(&mut current, line);
                let name = fields
                    .next()
                    .unwrap_or_else(|| panic!("line {line}: metric needs a name"));
                case.metric = match name {
                    "cosine" => Metric::Cosine,
                    "l2" => Metric::L2,
                    "ip" => Metric::Ip,
                    other => panic!("line {line}: unknown metric {other:?}"),
                };
            }
            "query" => {
                let case = case_mut(&mut current, line);
                case.query = fields.map(|field| number::<f32>(Some(field), "value", line)).collect();
            }
            "v" => {
                let case = case_mut(&mut current, line);
                let index = number::<usize>(fields.next(), "row", line);
                assert_eq!(index, case.vectors.len(), "line {line}: vector rows must be contiguous");
                let values: Vec<f32> = fields
                    .map(|field| number::<f32>(Some(field), "component", line))
                    .collect();
                assert_eq!(values.len(), case.dim, "line {line}: vector width");
                case.vectors.push(values);
            }
            "hit" => {
                let case = case_mut(&mut current, line);
                let index = number::<usize>(fields.next(), "row", line);
                let distance = number::<f32>(fields.next(), "distance", line);
                case.hits.push((index, distance));
            }
            tag => panic!("line {line}: unknown record {tag:?}"),
        }
    }

    if let Some(case) = current {
        cases.push(case);
    }
    cases
}

fn case_mut(current: &mut Option<Case>, line: usize) -> &mut Case {
    current
        .as_mut()
        .unwrap_or_else(|| panic!("line {line}: record before the first case"))
}

fn number<T: FromStr>(field: Option<&str>, what: &str, line: usize) -> T {
    let field = field.unwrap_or_else(|| panic!("line {line}: missing {what}"));
    field
        .parse::<T>()
        .unwrap_or_else(|_| panic!("line {line}: {what} {field:?} is not a valid number"))
}
